def create_cash_sources(apps, schema_editor):
    Account = apps.get_model("ledger", "Account")
    Transaction = apps.get_model("ledger", "Transaction")
    db_alias = schema_editor.connection.alias
    accounts = Account.objects.using(db_alias)
    legacy_cash = accounts.order_by("pk").first()
    if legacy_cash is None:
        return

    legacy_cash.code = "cash"
    legacy_cash.name = "Tunai"
    legacy_cash.type = "cash"
    legacy_cash.save(using=db_alias, update_fields=["code", "name", "type"])
    account_ids = {"cash": legacy_cash.pk}
    for code, name in (("bca", "BCA"), ("mandiri", "Mandiri"), ("ibk", "IBK")):
        bank_account, _created = accounts.get_or_create(
            code=code,
            defaults={
                "name": name,
                "type": "bank",
                "currency": legacy_cash.currency,
                "opening_balance": 0,
                "opening_balance_date": legacy_cash.opening_balance_date,
                "is_active": True,
            },
        )
        account_ids[code] = bank_account.pk

    transactions = Transaction.objects.using(db_alias)
    transactions.exclude(payment_method="transfer").update(
        account_id=account_ids["cash"],
        needs_account_review=False,
    )
    for code in ("bca", "mandiri", "ibk"):
        transactions.filter(payment_method="transfer", transfer_bank=code).update(
            account_id=account_ids[code],
            needs_account_review=False,
        )
    transactions.filter(payment_method="transfer").filter(
        models.Q(transfer_bank__isnull=True) | models.Q(transfer_bank="")
    ).update(
        account_id=account_ids["cash"],
        needs_account_review=True,
    )


